-- Migration 117: preserve every official NPCAppearData source row, including duplicate handles.
CREATE TABLE IF NOT EXISTS `god2_game`.`npc_appearance_source_rows` (
    `appearance_source_row_id` bigint NOT NULL,`client_build_id` varchar(64) NOT NULL,`client_entity_handle` int unsigned NOT NULL,
    `source_line` int NOT NULL,`section_row_index` int NOT NULL,`name_zh_tw` varchar(150) NOT NULL,`name_original` varchar(150) NOT NULL,
    `official_selector` int unsigned NOT NULL,`official_resource_type` tinyint unsigned NOT NULL,`official_resource_ordinal` tinyint unsigned NOT NULL,
    `source_sha256` char(64) NOT NULL,`raw_fields_json` json NOT NULL,PRIMARY KEY (`appearance_source_row_id`),
    UNIQUE KEY `ux_npc_appearance_source_row` (`client_build_id`,`section_row_index`),KEY `ix_npc_appearance_source_handle` (`client_build_id`,`client_entity_handle`),
    CONSTRAINT `fk_npc_appearance_source_identity` FOREIGN KEY (`client_build_id`,`client_entity_handle`) REFERENCES `god2_game`.`npc_appearance_identities` (`client_build_id`,`client_entity_handle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lossless official NPCAppearData source rows';

ON DUPLICATE KEY UPDATE `client_entity_handle`=VALUES(`client_entity_handle`),`source_line`=VALUES(`source_line`),`name_zh_tw`=VALUES(`name_zh_tw`),`name_original`=VALUES(`name_original`),`official_selector`=VALUES(`official_selector`),`official_resource_type`=VALUES(`official_resource_type`),`official_resource_ordinal`=VALUES(`official_resource_ordinal`),`source_sha256`=VALUES(`source_sha256`),`raw_fields_json`=VALUES(`raw_fields_json`);

